import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();

        System.out.println(x * y - computeValue(x, y));
        scanner.close();
    }

    private static int computeValue(int n, int m) {
        if (n < m) {
            int temp = n;
            n = m;
            m = temp;
        }

        if (m == 1) {
            Map<Integer, Integer> patternMap = new HashMap<>();
            patternMap.put(0, 0);
            patternMap.put(1, 1);
            patternMap.put(2, 2);
            patternMap.put(3, 3);
            patternMap.put(4, 2);
            patternMap.put(5, 1);
            return patternMap.get(n % 6);
        }

        if (n == 7) {
            if (m == 2) {
                return 2;
            }
            return (n * m) % 2;
        } else if (n >= 4) {
            return (n * m) % 2;
        } else {
            Map<String, Integer> pairMap = new HashMap<>();
            pairMap.put("3,2", 2);
            pairMap.put("3,1", 3);
            pairMap.put("2,2", 4);
            pairMap.put("2,1", 2);
            String key = n + "," + m;
            return pairMap.getOrDefault(key, (n * m) % 2);
        }
    }
}
